// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.navigation/** * NOUS — type-safe navigation routes. * * Each route is a value class implementing [NousRoute]. The Compose NavHost * in :feature:ui registers destinations by route's [path]. * * Why value classes: *   - Type-safe (can't pass `Route.Chat("123")` where `Route.Memory("456")` is expected) *   - Zero-allocation at runtime (compiled to plain strings) *   - Refactor-friendly (rename route → all call sites update) *//** Base interface for all NOUS navigation routes. */sealed interface NousRoute {    /** The route path used in NavHost (e.g., "chat", "memory/{memoryId}"). */    val path: String}// ─── Top-level destinations ─────────────────────────────────────────────────object Routes {    /** Splash / boot screen. */    data object Boot : NousRoute {        override val path = "boot"    }    /** Onboarding flow (model download, persona selection, privacy consent). */    data object Onboarding : NousRoute {        override val path = "onboarding"    }    /** Main chat / conversation screen. */    data object Chat : NousRoute {        override val path = "chat"    }    /** Specific conversation by ID. */    data class Conversation(val conversationId: String) : NousRoute {        override val path = "conversation/$conversationId"        companion object {            const val PATTERN = "conversation/{conversationId}"        }    }    /** Memory browser. */    data object Memory : NousRoute {        override val path = "memory"    }    /** Persona picker. */    data object Personas : NousRoute {        override val path = "personas"    }    /** Skills manager. */    data object Skills : NousRoute {        override val path = "skills"    }    /** Automation rules. */    data object Automation : NousRoute {        override val path = "automation"    }    /** Settings. */    data object Settings : NousRoute {        override val path = "settings"    }    /** Privacy dashboard. */    data object Privacy : NousRoute {        override val path = "settings/privacy"    }    /** AI Models manager (download / switch). */    data object Models : NousRoute {        override val path = "settings/models"    }    /** Audit log viewer. */    data object AuditLog : NousRoute {        override val path = "settings/audit-log"    }}/** Deep-link schemes for NOUS URIs (e.g., `nous://chat/new`). */const val NOUS_DEEP_LINK_SCHEME = "nous"